import test from 'node:test';
import assert from 'node:assert/strict';
import {INITIAL,simulate,compare,scheduled,validate} from './model.js';
import {definition,toToolState,fromToolState} from '../../../embed/definitions/lab-clocks.js';
import {validateState,applyControl} from '../../../embed/core/schema.js';
import {definitionMetadata} from '../../../embed/core/definition.js';
const state=patch=>({...structuredClone(INITIAL),...patch});
const clocks=(start=1,every=28)=>Object.fromEntries(['discovery','review','funding','delivery'].map(id=>[id,{start,every}]));
test('same-day discovery can inform review, funding and delivery in the declared order',()=>{const r=simulate(state({clocks:clocks()}));assert.deepEqual(r.trace.slice(0,4).map(t=>t.lane),['discovery','review','funding','delivery']);assert.equal(r.matches,1);assert.equal(r.averageAge,0);assert.equal(r.deliveries[0].need,'A');});
test('review cannot use future observations and an early delivery remains unused',()=>{const c=clocks();c.discovery.start=2;const r=simulate(state({clocks:c}));assert.equal(r.deliveries.length,0);assert.equal(r.unused,1);assert.match(r.trace.find(t=>t.lane==='review').detail,/No observation/);});
test('later evidence never rewrites the funded choice or earlier action',()=>{const c=clocks();c.discovery={start:1,every:7};c.delivery={start:1,every:7};const r=simulate(state({clocks:c}));assert.equal(r.deliveries[0].need,'A');assert.equal(r.deliveries.find(d=>d.day===8).need,'A');assert.equal(r.deliveries.find(d=>d.day===8).actual,'B');assert.equal(r.deliveries.find(d=>d.day===8).matches,false);});
test('a changed need may make old evidence wrong and later correct again',()=>{const c=clocks();c.delivery={start:1,every:7};const r=simulate(state({clocks:c}));assert.deepEqual(r.deliveries.map(d=>d.matches),[true,false,false,true]);assert.equal(r.deliveries.at(-1).age,21);});
test('review cost consumes a bounded budget including empty meetings',()=>{const c=clocks();c.discovery.start=2;c.review={start:1,every:1};const r=simulate(state({clocks:c,attention:1,reviewCost:1}));assert.equal(r.attentionUsed,1);assert.equal(r.skipped,27);assert.equal(r.matches,0);const free=simulate(state({clocks:c,attention:0,reviewCost:0}));assert.equal(free.skipped,0);assert.equal(free.attentionUsed,0);});
test('steady need makes extra review spend attention without improving actions',()=>{const c=clocks();c.delivery={start:1,every:7};const slow=simulate(state({scenario:'stable',clocks:c,attention:30}));c.review={start:1,every:1};const fast=simulate(state({scenario:'stable',clocks:c,attention:30}));assert.equal(slow.matches,fast.matches);assert.ok(fast.attentionUsed>slow.attentionUsed);});
test('attention exhausted early can miss a later change despite daily evidence',()=>{const c=clocks(1,1);const limited=simulate(state({scenario:'late',clocks:c,attention:8,reviewCost:1}));assert.equal(limited.deliveries.find(d=>d.day===16).need,'A');const later=structuredClone(c);later.review={start:16,every:28};const r=simulate(state({scenario:'late',clocks:later,attention:8,reviewCost:1}));assert.equal(r.deliveries.find(d=>d.day===16).need,'B');});
test('pinned timing is replayed under the same external events and attention assumptions',()=>{const pin=state({scenario:'changing',attention:0}),s=state({scenario:'stable',attention:30,reviewCost:0});assert.deepEqual(compare(s,pin),simulate({...s,clocks:pin.clocks}));assert.ok(compare(s,pin).matches>0);});
test('endpoints and strict portable validation reject malformed timing',()=>{assert.deepEqual(scheduled({start:28,every:28}),[28]);for(const s of [null,state({extra:1}),state({clocks:{...INITIAL.clocks,ghost:{start:1,every:1}}}),state({clocks:{...INITIAL.clocks,review:{start:0,every:1}}}),state({reviewCost:.1}),state({attention:Infinity})])assert.throws(()=>validate(s));});
test('article controls and handoff render the real timing at phone and desktop widths',()=>{const s=state();validateState(definition,s);const next=applyControl(definition,s,'review',2);assert.equal(next.clocks.review.start,2);assert.deepEqual(fromToolState(toToolState(next)),next);for(const width of [320,1100]){const out=definition.views.timing.render(next,{width});assert.match(out.svg,/<svg/);assert.match(out.summary,/attention used/);assert.ok(!out.svg.includes('undefined'));}});
test('article control identities remain portable while native field paths retain their names',()=>{assert.doesNotThrow(()=>definitionMetadata(definition));assert.deepEqual(definition.controls['review-cost'].path,['reviewCost']);assert.throws(()=>definitionMetadata({...definition,controls:{...definition.controls,reviewEvery:definition.controls['review-every']}}),/Invalid control identity/);});
